# 12 new MedDecode Encounter patients (drafts for instructor review).
def F(t,lay,d,red=False): return {'t':t,'lay':lay,'d':d,'red':red}
def A(by,say,*f,**k):
    o={'by':by,'say':say}
    if f: o['f']=list(f)
    o.update(k); return o
def V(vit,abn,*f): return {'by':'Vital signs','say':'Recorded.','vit':vit,'abn':abn,**({'f':list(f)} if f else {})}

