{'id':'M5','prog':'CCMA','title':'Chest pressure in the waiting room','cond':['Heart attack'],'sys':['Cardiovascular'],'age':'Adult',
 'name':'Walter Kim','ageText':'62-year-old man','scene':'Family medicine clinic. He came in for a medication refill. You are rooming him.',
 'open':[A('Walter',"Sorry, I'm a little out of breath. The walk from the parking lot got to me.")],
 'dflt':A('Walter',"No, nothing like that."),
 'a':{
  'cc':A('Walter',"I'm just here for my refills. But I've had this pressure in my chest since I walked in from the parking lot.",F('Chest pressure','pressure in the chest','a possible sign of a heart attack',True)),
  'chest':A('Walter',"It's like a tight band across my chest. It hasn't let up.",F('Persistent chest pressure','tight band across the chest','chest pressure that doesn\'t go away is an emergency sign',True)),
  'onset':A('Walter',"About twenty minutes ago.",F('Onset 20 minutes ago','started 20 minutes ago','ongoing for 20 minutes',True)),
  'region':A('Walter',"Mostly the middle, and my left shoulder aches too."),
  'breath':A('Walter',"I can't quite get a full breath.",F('Dyspnea','short of breath','difficult breathing')),
  'sweat':A('Walter',"Yeah, I'm sweating, and it's cool in here.",F('Diaphoresis','sweating','profuse sweating',True)),
  'nausea':A('Walter',"A little queasy."),
  'prov':A('Walter',"Sitting down hasn't helped."),
  'pmh':A('Walter',"High blood pressure and high cholesterol. My dad had a heart attack at 60."),
  'meds':A('Walter',"Lisinopril and atorvastatin. That's what I need refilled."),
  'allergies':A('Walter',"No allergies."),
  'vitals':V({'BP':'162/96','HR':'108','RR':'22','SpO2':'94%','Temp':'98.2°F'},['BP','HR','RR'],F('Tachycardia and hypertension','fast pulse, high blood pressure','abnormal vital signs with chest pressure',True)),
  'skin':A('Skin check',"Pale and sweaty.")
 },
 'key':[['cc|chest','Ask about the chest pressure','Chest pressure that won\'t go away is an emergency.'],
        ['onset','Ask when it started','Twenty minutes of pressure is serious.'],
        ['sweat','Ask about sweating','Sweating with chest pressure raises concern.'],
        ['breath','Ask about breathing','Shortness of breath adds to the concern.'],
        ['vitals','Take vital signs','A fast pulse and high blood pressure confirm the urgency.']],
 'end':{'q':'What do you do?','opts':[
   ["Stop rooming. Stay with him, alert the provider immediately, and follow the clinic's emergency protocol (including calling 911). Report: chest pressure for 20 minutes not relieved by rest, sweating, shortness of breath, HR 108, BP 162/96.",True,"Possible heart attack. In a clinic, the medical assistant's job is to recognize it, get the provider right away and follow the emergency protocol."],
   ["Finish rooming and let the provider see him in turn.",False,"Chest pressure with sweating and shortness of breath can't wait in line."],
   ["Tell him to drive to the emergency room.",False,"A person with possible heart attack symptoms should never drive himself."],
   ["Give him one of the clinic's aspirin and have him rest.",False,"Medical assistants don't give medication without a provider's order. Get the provider now."]]},
 'chartIt':[["He is sweating heavily.","Diaphoresis",["Diaphoresis","Diuresis","Dyspnea","Dysphoria"],"Diaphoresis means profuse sweating."],
            ["He's short of breath.","Dyspnea",["Dyspnea","Apnea","Orthopnea","Tachypnea"],"Dys- (difficult) + -pnea (breathing)."],
            ["His heart rate is 108.","Tachycardia",["Tachycardia","Bradycardia","Arrhythmia","Palpitations"],"Tachy- (fast) + cardi (heart) + -ia."]]},

